<!doctype html><title>Products</title><style>body{font:16px Arial;margin:40px}a,button{padding:8px;background:#4f46e5;color:white;border:0;text-decoration:none}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:10px;border-bottom:1px solid #ddd}.d{background:#b91c1c}</style><h1>Products</h1><a href="<?=site_url('products/create')?>">Add product</a> <form style="display:inline" method=post action="<?=site_url('logout')?>"><?php csrf_field(); ?><button>Logout</button></form><table><tr><th>Name</th><th>Description</th><th>Price</th><th>Quantity</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td><?=htmlspecialchars($p['product_name'], ENT_QUOTES, 'UTF-8')?></td><td><?=htmlspecialchars($p['description'], ENT_QUOTES, 'UTF-8')?></td><td>₱<?=number_format((float)$p['price'],2)?></td><td><?=htmlspecialchars((string)$p['quantity'], ENT_QUOTES, 'UTF-8')?></td><td><a href="<?=site_url('products/edit/'.$p['id'])?>">Edit</a> <form style="display:inline" method=post action="<?=site_url('products/delete/'.$p['id'])?>"><?php csrf_field(); ?><button class=d>Delete</button></form></td></tr><?php endforeach?></table>
